/**
 * Org-stream ORCHESTRATOR: the typed blocks of an `ei org export` stream →
 * the org's reference identities (plan §7 M1). Owns traversal, dispatch,
 * loud unknown-kind errors, and assembly — per-kind knowledge lives in
 * src/entities/org/ (data-facet modules assembled in src/graph/modules.ts).
 *
 * The stream is a frozen contract (M0, board item 218): data-source lookups
 * for cloud links / categories / AI provider connectors / groups, plus a
 * locals.org_apps namespace→id map. Anything else in the stream means the
 * contract drifted — loud error, never a silent drop (plan §4.3).
 *
 * Naming: the authoring key (`tsLabel`) is DERIVED from
 * the exported terraform label through the lossless bijection in
 * src/tf/labels.ts — no minting, no tiebreakers (ei guarantees per-type
 * label uniqueness; the bijection preserves it). The label itself is NOT
 * persisted anywhere: the key IS the label in camelCase clothing, and build
 * derives it back via tsLabelToTfLabel. The bijection is the stable naming
 * contract; changing it is an upgrade/migration event.
 */
import { DATA_FACET_BY_TYPE } from "../../graph/index.js";
import { isTfExpr, tfLabelToTsLabel } from "../tf/index.js";
export class OrgExtractError extends Error {
    constructor(message) {
        super(message);
        this.name = "OrgExtractError";
    }
}
export function extractOrg(doc) {
    const raw = {
        cloudLinks: [],
        categories: [],
        connectors: [],
        aiProviders: [],
        groups: [],
        phoneProviders: [],
    };
    let apps;
    let storedFunctions = [];
    for (const block of doc.blocks) {
        if (block.kind === "data") {
            const type = block.type ?? "";
            const kind = DATA_FACET_BY_TYPE.get(type);
            const orgBag = kind?.data.participates === true ? kind.data.orgBag : undefined;
            // A data facet without orgBag (e.g. elementum_user, foreign app) is
            // app-stream-only — presence here is contract drift like an unknown type.
            if (orgBag === undefined || kind?.data.participates !== true) {
                throw new OrgExtractError(`unexpected data source "${block.type}" in org export stream — the M0 contract grew; extend the extractor deliberately`);
            }
            const tfLabel = requireLabel(block);
            raw[orgBag].push({
                name: requireStringAttr(block, kind.data.lookupAttr),
                tfLabel,
                resourceType: type,
                // `provider_id` is a REAL ref only when the connector's provider was
                // also exported (`writeConnectorDataBlocks`, cmd/elementum/export/
                // org_export.go) — otherwise the bridge falls back to a
                // `provider_name` string, or emits neither at all for an orphaned
                // connector (no provider on the platform side). So the attribute's
                // mere absence is a legitimate dialect branch, not contract drift —
                // only demand `requireDataRef`'s shape when the attribute is
                // actually present; malformed-but-present still fails loud.
                providerRef: kind.data.providerRefAttr !== undefined && block.attrs[kind.data.providerRefAttr] !== undefined
                    ? requireDataRef(block, kind.data.providerRefAttr, tfLabel)
                    : undefined,
            });
            continue;
        }
        if (block.kind === "locals") {
            const orgApps = block.attrs["org_apps"];
            if (orgApps === undefined) {
                throw new OrgExtractError(`unexpected locals block (keys: ${Object.keys(block.attrs).join(", ")}) in org export stream`);
            }
            apps = requireStringMap(orgApps);
            if (block.attrs["org_stored_functions"] !== undefined) {
                storedFunctions = requireStoredFunctions(block.attrs["org_stored_functions"]);
            }
            continue;
        }
        throw new OrgExtractError(`unexpected ${block.kind} block in org export stream — org export is identity-level only`);
    }
    if (apps === undefined) {
        throw new OrgExtractError("org export stream has no locals.org_apps — is this really an org export?");
    }
    const connectors = withTsLabels(raw.connectors);
    const aiProviders = withTsLabels(raw.aiProviders);
    const providerRefs = new Set(aiProviders.map((provider) => `${provider.resourceType}.${provider.tfLabel}`));
    const diagnostics = connectors.flatMap((connector) => {
        if (connector.providerRef === undefined) {
            return [`connector "${connector.name}" (${connector.tfLabel}) has no resolved provider reference; skipped`];
        }
        const providerRefKey = `${connector.providerRef.resourceType}.${connector.providerRef.tfLabel}`;
        return providerRefs.has(providerRefKey)
            ? []
            : [`connector "${connector.name}" (${connector.tfLabel}) references provider "${providerRefKey}" which was not exported; skipped`];
    });
    return {
        cloudLinks: withTsLabels(raw.cloudLinks),
        categories: withTsLabels(raw.categories),
        connectors,
        aiProviders,
        groups: withTsLabels(raw.groups),
        phoneProviders: withTsLabels(raw.phoneProviders),
        storedFunctions,
        diagnostics,
        apps,
    };
}
function requireStoredFunctions(value) {
    if (!Array.isArray(value))
        throw new OrgExtractError("locals.org_stored_functions is not an array");
    return value.map((entry, index) => {
        if (typeof entry !== "object" || entry === null || Array.isArray(entry)) {
            throw new OrgExtractError(`locals.org_stored_functions[${index}] is not an object`);
        }
        const row = entry;
        const stringValue = (key) => {
            if (typeof row[key] !== "string")
                throw new OrgExtractError(`locals.org_stored_functions[${index}].${key} is not a string`);
            return row[key];
        };
        if (typeof row.configured !== "boolean")
            throw new OrgExtractError(`locals.org_stored_functions[${index}].configured is not a boolean`);
        if (!Array.isArray(row.parameter_types) || !row.parameter_types.every((item) => typeof item === "string")) {
            throw new OrgExtractError(`locals.org_stored_functions[${index}].parameter_types is not a string array`);
        }
        return {
            cloudLinkName: stringValue("cloud_link_name"),
            name: stringValue("name"),
            databaseName: stringValue("database_name"),
            schemaName: stringValue("schema_name"),
            functionType: stringValue("function_type"),
            configured: row.configured,
            parameterTypes: row.parameter_types,
            returnType: stringValue("return_type"),
        };
    });
}
/** Derive each identity's authoring key from its recorded tfLabel — pure,
 * lossless, and unique because ei's tfLabels are unique per type. */
function withTsLabels(entities) {
    return entities
        .map((e) => ({
        tsLabel: tfLabelToTsLabel(e.tfLabel),
        name: e.name,
        tfLabel: e.tfLabel,
        resourceType: e.resourceType,
        providerRef: e.providerRef,
    }))
        .sort((a, b) => a.tsLabel.localeCompare(b.tsLabel));
}
/** A `providerRefAttr` value must be a `data-attr` reference's `.id` — loud otherwise (contract drift, not silent). */
function requireDataRef(block, attr, tfLabel) {
    const v = block.attrs[attr];
    if (isTfExpr(v) && v.$expr === "data-attr" && v.path.length === 1 && v.path[0] === "id") {
        return { resourceType: v.type, tfLabel: v.label };
    }
    throw new OrgExtractError(`data "${block.type}" "${tfLabel}": expected "${attr}" to be a data source reference, got ${JSON.stringify(v)}`);
}
function requireLabel(block) {
    if (!block.label) {
        throw new OrgExtractError(`data "${block.type}" block is missing its label`);
    }
    return block.label;
}
function requireStringAttr(block, attr) {
    const v = block.attrs[attr];
    if (typeof v !== "string") {
        throw new OrgExtractError(`data "${block.type}" "${block.label}": expected string attribute "${attr}", got ${JSON.stringify(v)}`);
    }
    return v;
}
function requireStringMap(v) {
    if (typeof v !== "object" || v === null || Array.isArray(v)) {
        throw new OrgExtractError("locals.org_apps is not an object");
    }
    const out = {};
    for (const [k, val] of Object.entries(v)) {
        if (typeof val !== "string") {
            throw new OrgExtractError(`locals.org_apps["${k}"] is not a string`);
        }
        out[k] = val;
    }
    return out;
}
